from pathlib import Path
import base64, hashlib, shutil

DATA = base64.b64decode("""""")
EXPECTED = "a15f1e47ae2178035a41737c6cb4dbc0bd8a77a54dda57344058e4fbc3fef6ae"
assert hashlib.sha256(DATA).hexdigest() == EXPECTED

res = Path("video-compressor/app/src/main/res")
for density in ("mdpi","hdpi","xhdpi","xxhdpi","xxxhdpi"):
    d = res / f"mipmap-{density}"
    d.mkdir(parents=True, exist_ok=True)
    (d / "ic_launcher.png").write_bytes(DATA)
    (d / "ic_launcher_round.png").write_bytes(DATA)

for p in (
    res / "mipmap-anydpi-v26" / "ic_launcher.xml",
    res / "mipmap-anydpi-v26" / "ic_launcher_round.xml",
    res / "drawable" / "ic_launcher_foreground.xml",
    res / "drawable" / "ic_launcher_background.xml",
):
    if p.exists():
        p.unlink()

print("Installed pixel launcher icon:", EXPECTED)
